<script setup lang="ts">
import{clinicCommand,parseClinicCommand,sameClinicCommand}from'./clinic-command';
import{useSalesScope}from'./use-sales-scope';
import ClinicRecovery from'./ClinicRecovery.vue';import{clinicPendingTarget,validClinicSaved}from'./clinic-pending-status';import{ref,computed,onMounted,watch}from'vue';import{Building2,History,Clock3,Save,X,RefreshCw}from'@lucide/vue';
const props=defineProps<{staff:any}>(),emit=defineEmits(['unauthorized']),clinics=ref<any[]>([]),clinic=ref(''),detail=ref<any>(null),functions=ref<string[]>([]),profiles=ref<any[]>([]),rules=ref<any[]>([]),profileNext=ref<string|null>(null),ruleNext=ref<string|null>(null),busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),mode=ref(''),form=ref<any>({}),pending=ref<any>(null);
const canManage=computed(()=>functions.value.includes('clinic.manage')),key=()=> 'adc.clinicPending:'+props.staff.accountId,time=(s:string)=>new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
const profileTotal=ref<number|null>(null),ruleTotal=ref<number|null>(null),profileAsOf=ref(''),ruleAsOf=ref('');
const selection=ref(0),identity=()=>JSON.stringify([props.staff.accountId,props.staff.employeeId]),authScope=useSalesScope(identity),viewScope=useSalesScope(()=>JSON.stringify([identity(),clinic.value,selection.value]));
function clearView(){detail.value=null;profiles.value=[];rules.value=[];profileNext.value=null;ruleNext.value=null;profileTotal.value=null;ruleTotal.value=null;profileAsOf.value='';ruleAsOf.value='';mode.value='';form.value={};}
watch(clinic,()=>{selection.value++;clearView();},{flush:'sync'});
watch(()=>JSON.stringify(Object.fromEntries(Object.entries(form.value).filter(([k])=>k!=='checked'))),()=>{form.value.checked=false;},{flush:'sync'});
const cacheBlocked=ref(false),cacheError=ref('');
function restoreCache(){cacheBlocked.value=false;cacheError.value='';pending.value=null;try{const raw=sessionStorage.getItem(key());if(raw)pending.value=parseClinicCommand(raw,props.staff);}catch{cacheBlocked.value=true;cacheError.value='原诊所缓存损坏、身份不符或无法读取；已保留原记录并阻止新保存。';}}
function keep(p:any){const raw=sessionStorage.getItem(key());if(raw&&!sameClinicCommand(parseClinicCommand(raw,props.staff),p))throw Error('本机已是另一笔请求，未覆盖。');sessionStorage.setItem(key(),JSON.stringify(p));}
function markKnown(p:any,phase:string){pending.value={...p,phase,known:true};try{keep(pending.value);}catch{cacheError.value='已收到明确结果，本机状态未能写入；请只清理提示，不重办。';}}
class ApiError extends Error{constructor(readonly status:number,m:string){super(m);}}
async function api(path:string,body?:any,current:()=>boolean=()=>true){const own=authScope.capture(),a=new AbortController(),timer=setTimeout(()=>a.abort(),20000);try{const r=await fetch('/api/v1/clinics'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:a.signal}),b=await r.json();if(!r.ok){if(r.status===401&&own()&&current())emit('unauthorized');throw new ApiError(r.status,b.message||'诊所资料请求失败。');}return b;}finally{clearTimeout(timer);}}
const explain=(e:unknown)=>e instanceof Error?e.message:'请求失败。';
async function initialize(){const current=authScope.begin('initialize');loading.value=true;error.value='';try{restoreCache();const b=await api('/bootstrap',undefined,current);if(!current())return;clinics.value=b.clinics;functions.value=b.functions;clinic.value=clinics.value.some(c=>c.id===clinic.value)?clinic.value:b.clinics[0]?.id||'';if(clinic.value)await refresh();}catch(e){if(current())error.value=explain(e);}finally{if(current.active())loading.value=false;}}
function clearHistory(kind:'profile'|'rule'){if(kind==='profile'){profiles.value=[];profileNext.value=null;profileTotal.value=null;profileAsOf.value='';}else{rules.value=[];ruleNext.value=null;ruleTotal.value=null;ruleAsOf.value='';}}
async function history(kind:'profile'|'rule',more=false){const current=viewScope.begin('history:'+kind),next=kind==='profile'?profileNext.value:ruleNext.value,point=kind==='profile'?profileAsOf.value:ruleAsOf.value;if(more&&!next)return;if(!more)clearHistory(kind);try{const r=await api('/'+clinic.value+'/history-page?kind='+kind+(more?'&cursor='+encodeURIComponent(next!):''),undefined,current);if(!current())return;if(more&&r.asOf!==point)throw Object.assign(Error('历史读取时点已变化，请重新读取。'),{status:409});if(kind==='profile'){profiles.value=more?[...profiles.value,...r.items]:r.items;profileNext.value=r.next??null;profileTotal.value=r.total??r.items.length;profileAsOf.value=r.asOf??'';}else{rules.value=more?[...rules.value,...r.items]:r.items;ruleNext.value=r.next??null;ruleTotal.value=r.total??r.items.length;ruleAsOf.value=r.asOf??'';}}catch(e:any){if(!current())return;if([401,403].includes(e.status)){selection.value++;clearView();loading.value=false;}else if(e.status===409)clearHistory(kind);error.value=explain(e);}}

async function refresh(){if(!clinic.value)return;selection.value++;clearView();const current=viewScope.begin('detail');loading.value=true;error.value='';try{const r=await api('/'+clinic.value,undefined,current);if(!current())return;detail.value=r;await Promise.all([history('profile'),history('rule')]);}catch(e){if(current()){clearView();error.value=explain(e);}}finally{if(current.active())loading.value=false;}}
function open(m:string){if(cacheBlocked.value||pending.value)return;mode.value=m;error.value='';const d=detail.value;if(m==='profile')form.value={name:d.clinic.name,address:d.clinic.address||'',contactInfo:d.clinic.contactInfo||'',managerId:d.clinic.managerId||'',areaValue:d.clinic.areaValue||'',reason:'',checked:false};else{const r=d.latestRule;form.value={mode:'now',effectiveFrom:'',cancelLeadMinutes:r?.self_cancel_lead_minutes??'',rescheduleLeadMinutes:r?.self_reschedule_lead_minutes??'',selfServiceEnabled:r?.self_service_enabled??false,reason:'',checked:false};}}


function clearPending(value:any){if(busy.value||cacheBlocked.value)return false;try{const p=clinicCommand(value,props.staff),raw=sessionStorage.getItem(key());if(raw&&!sameClinicCommand(parseClinicCommand(raw,props.staff),p))throw Error('本机已是另一笔记录，未删除。');sessionStorage.removeItem(key());pending.value=null;cacheError.value='';notice.value='原结果已核对，仅清理本机提示。';return true;}catch(e){cacheError.value=explain(e);return false;}}
function clearVerified(value:any){if(busy.value||cacheBlocked.value)return;try{const p=clinicCommand(value,props.staff);if(!p.known)markKnown(p,'confirmed');clearPending(p);}catch(e){cacheError.value=explain(e);}}
async function submit(value:any,retry=false){if(busy.value||cacheBlocked.value)return;let p:any;try{p=clinicCommand(value,props.staff);if(p.known){error.value='原办理已有明确结果，只需清理提示。';return;}const raw=sessionStorage.getItem(key());if(raw){const stored=parseClinicCommand(raw,props.staff);if(stored.known||!sameClinicCommand(stored,p))throw Error('本机已有其他或已完成请求，未发送。');}}catch(e){cacheBlocked.value=true;cacheError.value=explain(e);return;}pending.value=p;try{keep(p);}catch{if(!retry)pending.value=null;error.value='本机原请求未保存，本次没有发送；请恢复存储后再试。';return;}const own=authScope.capture();busy.value=true;error.value='';let committed=false;try{const r=await api(p.path,p.body,own);if(!own())return;validClinicSaved(p,r);committed=true;markKnown(p,'confirmed');mode.value='';busy.value=false;clearPending(p);busy.value=true;notice.value='已保存，原资料和已有预约截止保持可追查。 保存版本 '+r.version;await refresh();if(own()&&error.value)error.value='已保存，资料刷新未完成，请重新读取，勿重新办理。 '+error.value;}catch(e){if(!own())return;error.value=explain(e);if(committed){error.value='已保存，资料刷新未完成，请重新读取，勿重新办理。 '+error.value;}else if(!retry&&e instanceof ApiError&&e.status>=400&&e.status<500&&e.status!==401){markKnown(p,'rejected');busy.value=false;clearPending(p);busy.value=true;}else{pending.value={...p,phase:'pending',known:false};mode.value='';error.value+=' 结果暂不明确，请保留原请求并先只读核实。';}}finally{if(own())busy.value=false;}}

watch(identity,()=>{clinics.value=[];functions.value=[];clinic.value='';clearView();pending.value=null;busy.value=false;loading.value=false;error.value='';notice.value='';void initialize();},{flush:'sync'});

async function save(){if(cacheBlocked.value||busy.value||pending.value)return;try{if(sessionStorage.getItem(key())){restoreCache();error.value='请先处理本机原记录，未发送新保存。';return;}}catch{cacheBlocked.value=true;cacheError.value='无法读取本机记录，未发送新保存。';return;}const path='/'+clinic.value+(mode.value==='profile'?'/profile':'/rules'),f=form.value;const body=mode.value==='profile'?{requestId:crypto.randomUUID(),version:detail.value.clinic.version,name:f.name,address:f.address,contactInfo:f.contactInfo||null,managerId:f.managerId||null,areaValue:f.areaValue||null,areaUnit:f.areaValue?'m²':null,reason:f.reason,checked:f.checked}:{requestId:crypto.randomUUID(),baseRuleId:detail.value.latestRule?.rule_version_id||null,mode:f.mode,effectiveFrom:f.mode==='now'?null:new Date(f.effectiveFrom+ '+08:00').toISOString(),cancelLeadMinutes:f.cancelLeadMinutes===''?null:Number(f.cancelLeadMinutes),rescheduleLeadMinutes:f.rescheduleLeadMinutes===''?null:Number(f.rescheduleLeadMinutes),selfServiceEnabled:f.selfServiceEnabled,reason:f.reason,checked:f.checked};await submit({path,body});}
defineExpose({refresh:initialize});onMounted(initialize);
</script>
<template><div class="clinic-workspace"><div v-if="cacheError" class="b-alert error">{{cacheError}}<button class="b-button outline" :disabled="busy||loading" @click="restoreCache">重新读取本机记录</button></div><div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert success" role="status">{{notice}}</div><ClinicRecovery v-if="pending" :staff="staff" :pending="pending" :busy="busy" @clear="clearVerified" @retry="submit($event,true)"/>
<section class="b-card cm-head"><div><div class="b-eyebrow">CLINIC FOUNDATION</div><h2><Building2 :size="24"/>诊所资料与自助规则</h2><p>资料按诊所维护，规则另存版本，已有预约的已告知截止保持。</p></div><label>维护诊所<select v-model="clinic" :disabled="busy||loading||!!pending||cacheBlocked" @change="refresh"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="b-button outline" :disabled="busy||loading" @click="refresh"><RefreshCw :size="17"/>重新读取</button></section>
<template v-if="detail"><section class="b-card cm-block"><div class="cm-title"><div><h3>诊所基础资料</h3><p>稳定标识 {{detail.clinic.id.slice(0,8).toUpperCase()}} · 当前版本 {{detail.clinic.version}}</p></div><button v-if="canManage" class="b-button" :disabled="busy||loading||!!pending||cacheBlocked" @click="open('profile')">维护基础资料</button></div><dl class="cm-fields"><div><dt>诊所名称</dt><dd>{{detail.clinic.name}}</dd></div><div><dt>地址</dt><dd>{{detail.clinic.address||'尚未登记'}}</dd></div><div><dt>主管</dt><dd>{{detail.clinic.managerName||'尚未核实登记'}}</dd></div><div><dt>联系方式</dt><dd>{{detail.clinic.contactInfo||'尚未登记'}}</dd></div><div><dt>面积</dt><dd>{{detail.clinic.areaValue?detail.clinic.areaValue+' '+detail.clinic.areaUnit:'尚未核实登记'}}</dd></div><div><dt>最近资料时点</dt><dd>{{time(detail.clinic.updatedAt)}}</dd></div></dl><p class="b-help">维护资料不建立执业、排班或权限，也不迁移原业务归属。本批不办理新增诊所或停业安排。</p></section>
<section class="b-card cm-block"><div class="cm-title"><div><h3><Clock3 :size="20"/>患者自助预约规则</h3><p>取消与改约分别设置；分钟数是预约开始前需预留的时间。</p></div><button v-if="canManage" class="b-button" :disabled="busy||loading||!!pending||cacheBlocked" @click="open('rule')">新增规则版本</button></div><div v-if="detail.currentRule" class="cm-rule"><span class="b-pill active">当前适用 v{{detail.currentRule.version_no}}</span><div class="cm-rule-values"><div><small>自助取消提前</small><strong>{{detail.currentRule.self_cancel_lead_minutes}}<span> 分钟</span></strong></div><div><small>自助改约提前</small><strong>{{detail.currentRule.self_reschedule_lead_minutes}}<span> 分钟</span></strong></div><div><small>自助预约入口</small><strong>{{detail.currentRule.self_service_enabled?'可用':'暂停'}}</strong></div></div><p>生效 {{time(detail.currentRule.effective_from)}}</p></div><p v-else class="b-alert warning">当前没有适用规则，请联系前台；不猜截止参数。</p><p v-if="detail.latestRule?.rule_version_id!==detail.currentRule?.rule_version_id" class="b-alert warning">已安排未来规则 v{{detail.latestRule?.version_no}}，生效 {{time(detail.latestRule?.effective_from)}}。本批只能继续追加更晚版本，不能覆盖或向前插入。</p><p class="b-help">严格早于截止且尚未到院才能自助变更。0分钟仍须在预约开始前。新规则只供新预约及成功改约采用；暂停自助不取消旧预约，旧约取消仍按原规则；改约目的安排须满足当前可用规则。超过开始5分钟由前台联系，窗口结束仍须人工核实未到。</p></section>
<section class="b-card cm-block"><h3><History :size="20"/>基础资料历史</h3><p v-if="profileTotal!==null" class="b-help">已加载 {{profiles.length}} / 共 {{profileTotal}} 版</p><p v-if="profileTotal===0">尚未办理资料变更；原资料会在首次维护时保留基础快照。</p><article v-for="p in profiles" :key="p.id" class="cm-history"><div class="cm-title"><strong>v{{p.version}} · {{p.name}}</strong><span>{{p.initialCapture?'首次纳入历史的原资料':'已保存版本'}}</span></div><p>{{p.address}} · {{p.contactInfo||'联系方式未登记'}}</p><p>主管 {{p.managerName||'未核实登记'}} · 面积 {{p.areaValue?p.areaValue+' '+p.areaUnit:'未核实登记'}}</p><small>原资料时点 {{time(p.updatedAt)}} · 本次留存 {{time(p.registeredAt)}} · 办理人 {{p.actorName}}</small><p>依据：{{p.reason}}</p></article><button v-if="profileNext" class="b-button outline" :disabled="busy||loading" @click="history('profile',true)">继续加载资料历史</button></section>
<section class="b-card cm-block"><h3><History :size="20"/>预约规则历史及未来安排</h3><p v-if="ruleTotal!==null" class="b-help">已加载 {{rules.length}} / 共 {{ruleTotal}} 版</p><article v-for="r in rules" :key="r.rule_version_id" class="cm-history"><div class="cm-title"><strong>v{{r.version_no}} · {{r.self_service_enabled?'自助可用':'自助暂停'}}</strong><span>生效 {{time(r.effective_from)}}</span></div><p>取消提前 {{r.self_cancel_lead_minutes}} 分钟 · 改约提前 {{r.self_reschedule_lead_minutes}} 分钟</p><small>{{r.actor_name}} · 记录 {{time(r.created_at)}}</small><p>依据：{{r.reason||'既有初始化配置；未补造历史修改依据'}}</p></article><button v-if="ruleNext" class="b-button outline" :disabled="busy||loading" @click="history('rule',true)">继续加载规则历史</button></section></template><p v-else-if="!loading">没有当前可维护的诊所资料。</p>
<div v-if="mode" class="b-backdrop"><form class="b-dialog cm-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭诊所资料办理" :disabled="busy||!!pending||cacheBlocked" @click="mode='' "><X :size="22"/></button><div class="b-eyebrow">CLINIC FOUNDATION</div><h2>{{mode==='profile'?'核对并维护诊所资料':'新增患者自助规则版本'}}</h2><p>{{detail.clinic.name}} · 稳定标识 {{detail.clinic.id.slice(0,8).toUpperCase()}}</p><div v-if="error" class="b-alert error" role="alert">{{error}}</div><template v-if="mode==='profile'"><label>诊所名称<input v-model="form.name" required maxlength="150" :disabled="busy||!!pending||cacheBlocked"/></label><label>诊所地址<input v-model="form.address" required maxlength="1000" :disabled="busy||!!pending||cacheBlocked"/></label><label>主管<select v-model="form.managerId" :disabled="busy||!!pending||cacheBlocked"><option value="">未核实登记</option><option v-if="form.managerId&&!detail.managers.some((m:any)=>m.id===form.managerId)" :value="form.managerId" disabled>原主管当前任职不符，请重新核对</option><option v-for="p in detail.managers" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>诊所联系方式<input v-model="form.contactInfo" maxlength="500" :disabled="busy||!!pending||cacheBlocked" placeholder="未知可留空"/></label><label>面积（平方米）<input v-model="form.areaValue" inputmode="decimal" :disabled="busy||!!pending||cacheBlocked" placeholder="未知可留空；不推测面积"/></label></template>
<template v-else><p class="b-help">基于最新版本 {{detail.latestRule?.version_no||'无'}} 追加；已有预约保留原规则和截止，不统一修改。</p><div class="b-two-fields"><label>自助取消提前分钟数<input v-model="form.cancelLeadMinutes" type="number" min="0" max="525600" step="1" required :disabled="busy||!!pending||cacheBlocked"/></label><label>自助改约提前分钟数<input v-model="form.rescheduleLeadMinutes" type="number" min="0" max="525600" step="1" required :disabled="busy||!!pending||cacheBlocked"/></label></div><label>自助预约入口<select v-model="form.selfServiceEnabled" :disabled="busy||!!pending||cacheBlocked"><option :value="true">可用</option><option :value="false">暂停新自助预约</option></select></label><label>生效安排<select v-model="form.mode" :disabled="busy||!!pending||cacheBlocked"><option value="now">本次保存时立即生效</option><option value="scheduled">指定未来时刻</option></select></label><label v-if="form.mode==='scheduled'">未来生效时刻（北京时间）<input v-model="form.effectiveFrom" type="datetime-local" step="1" required :disabled="busy||!!pending||cacheBlocked"/></label><p class="b-help">技术上限525600分钟。不追溯修改，已有未来版本时只能追加更晚安排。</p></template><label>本次维护依据<textarea v-model="form.reason" rows="2" required maxlength="1000" :disabled="busy||!!pending||cacheBlocked"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.checked" required :disabled="busy||!!pending||cacheBlocked"/><span>{{mode==='profile'?'已核对本诊所标识、完整资料及未知项，保留原业务归属。':'已明确核对生效安排，原预约采用的规则及已告知截止保持不变。'}}</span></label><button class="b-button full" :disabled="busy||!!pending||cacheBlocked"><Save :size="17"/>{{busy?'保存并核对…':'确认保存'}}</button></form></div></div></template>
<style scoped>.clinic-workspace{display:grid;grid-template-columns:minmax(0,1fr);gap:24px;min-width:0}.cm-head,.cm-block{padding:28px}.cm-head,.cm-title{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.cm-head h2,.cm-block h3{display:flex;gap:10px;align-items:center}.cm-head h2{margin:10px 0;font-size:25px}.cm-head p,.cm-title p{color:#76877d;line-height:1.8}.cm-head label,.cm-dialog label{display:grid;gap:9px;color:#53675c;font-size:14px}.cm-head select,.cm-dialog input:not([type=checkbox]),.cm-dialog select,.cm-dialog textarea{border:1px solid #dce5dc;border-radius:8px;background:white;padding:12px;min-width:0;font:inherit}.cm-block h3{margin-top:0}.cm-fields{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:25px 0}.cm-fields dt{font-size:13px;color:#84948a}.cm-fields dd{margin:9px 0 0;line-height:1.8;overflow-wrap:anywhere}.cm-rule{border-radius:12px;background:#f3f7f3;padding:22px}.cm-rule-values{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:20px}.cm-rule-values small{color:#6d8275}.cm-rule-values strong{display:block;font-size:27px;color:#286e5b;margin:12px 0}.cm-rule-values strong span{font-size:14px}.cm-rule p{font-size:13px;color:#7d8e82}.cm-history{padding:22px 0;border-top:1px solid #e7eee7}.cm-history p{font-size:14px;line-height:1.8;overflow-wrap:anywhere}.cm-history small,.cm-history .cm-title span{font-size:12px;line-height:1.8;color:#809085}.cm-dialog{max-width:660px}.cm-dialog>label,.cm-dialog .b-two-fields{margin:18px 0}.cm-dialog .b-checkbox{display:flex;align-items:flex-start;line-height:1.8}.cm-dialog p{line-height:1.8}.cm-block .b-help{line-height:1.9}@media(max-width:760px){.cm-head,.cm-block{padding:20px}.cm-head h2{font-size:22px}.cm-fields{grid-template-columns:1fr}.cm-rule-values{grid-template-columns:1fr 1fr}.cm-head>label{width:100%}.cm-title>.b-button{width:100%}}</style>
